import React, { InputHTMLAttributes, useState, useMemo } from 'react';
import dayjs from 'dayjs';
import timezone from 'dayjs/plugin/timezone';
import utc from 'dayjs/plugin/utc';
import { Locales } from '@getvim/translate';
import { date, time } from '../../../lib/dateFormatter';
import { CommonFormats } from '../../../lib/commonFormats';
import { LabeledInput, InputStyleWrapper, InputStyle } from '../../../atoms';
import { DateTimePickerFieldProps, FormValues } from './types';
import DateTimeForm from './form';

import './index.less';

dayjs.extend(timezone);
dayjs.extend(utc);

export interface DateTimePickerProps
  extends DateTimePickerFieldProps,
    Omit<InputHTMLAttributes<HTMLInputElement>, 'name' | 'onChange'> {
  active?: boolean;
  htmlFor: string;
  value?: string;
  locale?: Locales;
}

function DateTimePicker({
  active,
  value,
  onChange,
  hover,
  alwaysShow,
  disableWeekend,
  showNewTimeField,
  timeZone,
  onCalendarStatusChange,
  locale = Locales.en,
  ...props
}: DateTimePickerProps) {
  const [showCalendarPicker, setShowCalendarPicker] = useState(false);
  const [formattedDateTime, setFormattedDateTime] = useState(
    value ? date(value, timeZone, locale, CommonFormats.DEFAULT_DATE_AND_TIME) : '',
  );

  const onFormSubmit = ({ datePicker, timePicker }: FormValues) => {
    const formattedDate = dayjs(datePicker).format(CommonFormats.FULL_NUMBERS_DATE);
    const dateTime = dayjs
      .tz(`${formattedDate} ${timePicker}`, CommonFormats.DEFAULT_DATE_AND_TIME, timeZone)
      .utc()
      .toISOString();

    onChange?.(dateTime);
    setShowCalendarPicker(false);
    onCalendarStatusChange?.(false, dateTime);
  };

  const changeListener = ({ datePicker, timePicker }: FormValues) => {
    let newFormattedTime = formattedDateTime;

    if (timePicker) {
      newFormattedTime =
        newFormattedTime.length >= 10
          ? `${newFormattedTime.slice(0, 10)} ${timePicker}`
          : timePicker;
    }
    if (datePicker) {
      const formattedDate = dayjs(datePicker).format(CommonFormats.FULL_NUMBERS_DATE);
      newFormattedTime =
        newFormattedTime.length >= 10
          ? `${formattedDate} ${newFormattedTime.slice(11)}`
          : `${formattedDate} ${newFormattedTime}`;
    }

    setFormattedDateTime(newFormattedTime);
    onCalendarStatusChange?.(true, newFormattedTime);
  };

  const initialFormValues = useMemo(
    () => ({
      datePicker: value
        ? dayjs(date(value, timeZone, locale, CommonFormats.FULL_NUMBERS_DATE)).toDate()
        : undefined,
      timePicker: value ? time(value, timeZone, CommonFormats.HOURS_24_TIME) : undefined,
    }),
    [value, timeZone, locale],
  );

  return (
    <div>
      <InputStyleWrapper inputStyle={InputStyle.clean}>
        <LabeledInput
          type="text"
          onClick={() => {
            if (showCalendarPicker) {
              setFormattedDateTime('');
              try {
                (document.activeElement as HTMLElement).blur();
                // eslint-disable-next-line no-empty
              } catch (e) {}
            }
            setShowCalendarPicker(!showCalendarPicker);
            onCalendarStatusChange?.(!showCalendarPicker, formattedDateTime);
          }}
          value={formattedDateTime}
          readOnly
          {...props}
          active={active || !!formattedDateTime}
        />
      </InputStyleWrapper>

      {(alwaysShow || showCalendarPicker) && (
        <DateTimeForm
          showNewTimeField={showNewTimeField}
          disableWeekend={disableWeekend}
          changeListener={changeListener}
          initialValues={initialFormValues}
          onSubmit={onFormSubmit}
          hover={hover}
        />
      )}
    </div>
  );
}

export default DateTimePicker;
