import { Struct, assert } from 'superstruct';
import { defineMessages } from 'react-intl';

type Errors = {
  [key: string]: string | { custom: string };
};
const messages = defineMessages({
  required: {
    defaultMessage: ' is required',
    id: 'schemaValidator.required',
  },
  invalid: {
    defaultMessage: ' is invalid',
    id: 'schemaValidator.invalid',
  },
});

export const validateWithMessages = <T>(
  schema: Struct<T>,
  values: unknown,
  intl: { formatMessage: (arg0: { defaultMessage: string; id: string }) => any },
) => {
  try {
    assert(values, schema);
  } catch (e: any) {
    const errors: Errors = {};
    // eslint-disable-next-line no-restricted-syntax
    for (const failure of e.failures()) {
      const { value, path } = failure;
      const field = path[0];
      if (value === undefined) {
        errors[field] = intl.formatMessage(messages.required);
      } else {
        errors[field] = intl.formatMessage(messages.invalid);
      }
    }
    return errors;
  }
  return {};
};
