import React from 'react';
import { Field } from 'react-final-form';
import { DateTimePickerFieldProps } from './types';
import DateTimePicker from './view';

function DateTimePickerField({
  name,
  label,
  hover,
  alwaysShow,
  disableWeekend,
  showNewTimeField,
  timeZone,
  onChange,
  placeholder,
  onCalendarStatusChange,
}: DateTimePickerFieldProps) {
  return (
    <Field
      name={name}
      render={({ meta, input }) => (
        <DateTimePicker
          htmlFor={name}
          label={label}
          placeholder={placeholder}
          active={meta.active || input.value}
          hover={hover}
          alwaysShow={alwaysShow}
          showNewTimeField={showNewTimeField}
          disableWeekend={disableWeekend}
          timeZone={timeZone}
          onCalendarStatusChange={onCalendarStatusChange}
          {...input}
          onChange={(dateTime) => {
            input.onChange(dateTime);
            onChange?.(dateTime);
          }}
        />
      )}
    />
  );
}

export default DateTimePickerField;
