import React from 'react';
import { Form } from 'react-final-form';
import classNames from 'classnames';
import { defineMessages } from 'react-intl';
import { object, string, date as dateSchema, pattern } from 'superstruct';
import { useTranslation } from '@getvim/translate';
import { validateWithMessages } from '../../../lib/schemaValidator';
import { Button, InputStyle, InputStyleWrapper } from '../../../atoms';
import { FormTimeInput, TimePicker } from '../../../molecules';
import CalendarPicker from '../calendarPicker';
import { FormValues } from './types';
import es from './translations/es.json';

const messages = defineMessages({
  timePickerLabel: {
    defaultMessage: 'Time',
    id: 'atomic.dateTimePicker.timePickerLabel',
  },
  next: {
    defaultMessage: 'Next',
    id: 'atomic.dateTimePicker.next',
  },
});

interface DateTimeFormProps {
  hover?: boolean;
  disableWeekend?: boolean;
  showNewTimeField?: boolean;
  initialValues: FormValues;
  changeListener: (values: FormValues) => void;
  onSubmit: (values: FormValues) => void;
}

const schema = object({
  datePicker: dateSchema(),
  timePicker: pattern(string(), /^(0\d|1\d|2[0-3]):[0-5]\d$/),
});

function DateTimeForm({
  onSubmit,
  changeListener,
  initialValues,
  hover,
  disableWeekend,
  showNewTimeField = true,
}: DateTimeFormProps) {
  const intl = useTranslation({ es } as any);

  return (
    <Form
      onSubmit={onSubmit}
      initialValues={initialValues}
      validate={(values) => validateWithMessages(schema, values, intl)}
      render={({ handleSubmit, form, hasValidationErrors }) => (
        <div>
          <form className={classNames('date-time-picker', { hover })} onSubmit={handleSubmit}>
            <CalendarPicker
              name="datePicker"
              className="date-calendar-picker"
              disableWeekend={disableWeekend}
              changeListener={(event) => changeListener({ datePicker: event as Date })}
            />
            <div className="datetime-footer margin-top-30">
              {showNewTimeField ? (
                <FormTimeInput
                  name="timePicker"
                  label={intl.formatMessage(messages.timePickerLabel)}
                  className="datetime-time-picker"
                  changeListener={(event) => changeListener({ timePicker: event })}
                />
              ) : (
                <InputStyleWrapper inputStyle={InputStyle.smallMedium}>
                  <TimePicker
                    name="timePicker"
                    label={intl.formatMessage(messages.timePickerLabel)}
                    className="datetime-time-picker"
                    changeListener={(event) => changeListener({ timePicker: event })}
                  />
                </InputStyleWrapper>
              )}
              <Button
                text={intl.formatMessage(messages.next)}
                buttonType="small"
                disabled={hasValidationErrors}
                onClick={() => form.submit()}
              />
            </div>
          </form>
        </div>
      )}
    />
  );
}

export default DateTimeForm;
